      "path": "src/queue-view.ts",
      "sha256": "4d6ee92e40374d4dd4c6a49a3a20a6caf34e7f2d61a32a230c8ecf54691b5c49"
    },
    {
      "id": "start-vector",
      "path": "assets/start.svg",
      "sha256": "ee2ba2fe20bd09a2c9a9c96d889f766e8af80fcdf704e8172934135e2b7e12d3"
    }
  ],
  "assets": [
    {
      "id": "queue.ready",
      "kind": "static_status_icon",
      "purpose": "Show successful completion as Ready in both full and compact status cells; propose this as the representative family sample.",
      "status": "in_progress",
      "consumers": [
        {
          "source": "queue-view",
          "symbol": "statusVisuals.succeeded",
          "usage": "Maps succeeded to the Ready image path and frame count."
        },
        {
          "source": "queue-view",
          "symbol": "statusCell",
          "usage": "Full status consumer returns the shared succeeded descriptor."
        },
        {
          "source": "queue-view",
          "symbol": "compactStatus",
          "usage": "Compact status consumer returns the same succeeded descriptor; reuse one asset."
        },
        {
          "source": "queue-state",
          "symbol": "stateAfter",
          "usage": "An ok result transitions to succeeded, which resolves to the Ready visual."
        }
      ],
      "existing": [
        {
          "path": "assets/ready-confirmed.png",
          "role": "Current Ready destination is missing; assets/ready.png is superseded. Existing attempts remain retained."
        }
