        {
          "property": "cell_size_px",
          "value": [
            16,
            16
          ],
          "authority": "requirement",
          "sources": [
            "brief",
            "queue-view"
          ],
          "reason": "BRIEF fixes logical status cells and display.cell agrees."
        },
        {
          "property": "background",
          "value": "transparent",
          "authority": "requirement",
          "sources": [
