import json
old=json.load(open('.pixl/plar-history/0ede0be80131e8c4b071fe06fb4318d69148a4f80282d3b95c49f9f3e377df20.json',encoding='utf-8'))
new=json.load(open('plar.txt',encoding='utf-8'))
print("== PLAR DIFF 0ede -> 180a")
for k in old:
    if k!='assets' and old[k]!=new.get(k): print("top-level changed:",k)
oa={a['id']:a for a in old['assets']}; na={a['id']:a for a in new['assets']}
for aid in oa:
    for f in oa[aid]:
        if oa[aid][f]!=na[aid].get(f): print(" ",aid,"field changed:",f)
def req(a): return {k:v for k,v in a.items() if k not in ('status','next','evidence','production')}
print("requirements-view identical:", all(req(oa[a])==req(na[a]) for a in oa))
print("evidence count old/new", len(oa['queue.ready']['evidence']), len(na['queue.ready']['evidence']))
for e in na['queue.ready']['evidence'][len(oa['queue.ready']['evidence']):]: print("   +", e['path'])
print("next:", na['queue.ready']['next'][:300])
# rev1 vs rev2 packet diff
r1=json.load(open('work/queue.ready-handoff/request-review.json',encoding='utf-8'))
r2=json.load(open('work/queue.ready-handoff/revision-2/request-review.json',encoding='utf-8'))
print("\n== PACKET rev1 -> rev2 top-level keys changed:", [k for k in set(r1)|set(r2) if r1.get(k)!=r2.get(k)])
for s1,s2 in zip(r1['sources'],r2['sources']):
    if s1!=s2: print(" source changed:", s2['path'], s2.get('locators'))
print(" criteria:", r2['criteria'])
print(" revision block:", json.dumps(r2.get('revision'),indent=1)[:3000])
print(" review_status:", r2['review_status'])
print(" plar:", r2['plar'])
p1=json.load(open('work/queue.ready-handoff/candidate-plan.json',encoding='utf-8'))
p2=json.load(open('work/queue.ready-handoff/revision-2/candidate-plan.json',encoding='utf-8'))
print("\n== PLAN rev1 -> rev2")
for c1,c2 in zip(p1['outputs'][0]['criteria'],p2['outputs'][0]['criteria']):
    diff=[k for k in c1 if c1[k]!=c2.get(k)]
    if diff: print(" ",c2['id'],"changed:",diff); print("   NEW BASIS:", c2['basis'])
print(" other plan fields equal:", {k:p1[k]==p2[k] for k in p1 if k!='outputs'}, "contract equal:", p1['outputs'][0]['contract']==p2['outputs'][0]['contract'])
ch=json.load(open('work/queue.ready-handoff/revision-2/candidate-plan-changes.json',encoding='utf-8'))
print("\n== CHANGES rev2 section:", json.dumps(ch.get('revision_2'),indent=1)[:2500])
print(" corrected_plan:", ch.get('corrected_plan'))
EOF

