import json, hashlib, pathlib
root=pathlib.Path('.')
hr=json.load(open('HANDOFF-RESULT.json',encoding='utf-8'))
print("HANDOFF-RESULT.json valid JSON; sha256", hashlib.sha256(open('HANDOFF-RESULT.json','rb').read()).hexdigest())
bad=[]
def check(path, sha):
    p=root/path
    if not p.is_file(): bad.append(("missing",path)); return
    h=hashlib.sha256(p.read_bytes()).hexdigest()
    if sha and h!=sha: bad.append(("hash-mismatch",path,sha[:12],h[:12]))
check(hr['final_handoff']['path'], hr['final_handoff']['sha256'])
check(hr['final_handoff']['supersedes']['path'], hr['final_handoff']['supersedes']['sha256'])
check(hr['independent_comparison']['path'], hr['independent_comparison']['sha256'])
check(hr['independent_comparison']['compared_packet']['path'], hr['independent_comparison']['compared_packet']['sha256'])
check(hr['independent_comparison']['compared_criteria']['path'], hr['independent_comparison']['compared_criteria']['sha256'])
for a in hr['new_artifacts_this_stage']: check(a['path'], a['sha256'])
h=hr['historical_contract_and_acceptance_unchanged']
for k in ('request_review_packet','candidate_plan','provider_arguments','connection','request_stage_caller_review','delivery_caller_review','delivery_result','state','delivered_artifact','preserved_start'):
    check(h[k]['path'], h[k]['sha256'])
for r in h['previous_stage_results']: check(r['path'], r['sha256'])
for p,s in h['sources_unchanged'].items(): check(p,s)
print("link check problems:", bad or "none")
# caller-review internal links
cr=json.load(open('work/queue.ready-handoff/caller-review.json',encoding='utf-8'))
bad2=[]
for k,v in cr['reviewed'].items():
    if isinstance(v,dict) and 'path' in v and 'sha256' in v:
        p=root/v['path']; hh=hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() else None
        if hh!=v['sha256']: bad2.append((k,v['path']))
for p,s in cr['independent_verification']['historical_bytes_unchanged']['files'].items():
    if hashlib.sha256((root/p).read_bytes()).hexdigest()!=s: bad2.append(("hist",p))
print("caller-review link problems:", bad2 or "none")
EOF
echo "== final tree of stage files" && find work/queue.ready-handoff .pixl/handoffs -type f | sort && git -C . status --short . 2>/dev/null | head -40

